args.sql:
SELECT vpnratio, proxycount, ipcountrynum, 
       0.4 * vpnratio as tei_part1,
       0.3 * proxycount / 10.0 as tei_part2,
       0.3 * ipcountrynum / 20.0 as tei_part3,
       0.4 * vpnratio + 0.3 * proxycount / 10.0 + 0.3 * ipcountrynum / 20.0 as tei_total
FROM technicalinfo WHERE techkey = (
    SELECT technetref FROM networkmetrics WHERE netkey = (
        SELECT netsessref FROM sessionbehavior WHERE sessprofref = (
            SELECT profkey FROM profile WHERE profaccref = 'FA470938'
        )
    )
);

SELECT vpnratio, proxycount, ipcountrynum,
       vpnratio + proxycount / 10.0 + ipcountrynum / 20.0 as tei_simple
FROM technicalinfo LIMIT 5;
